def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if n < 2:
        return n
    if n < 4:
        raise ValueError("%d is not a perfect square" % n)
    # Newton's method: monotonically non-increasing integer sequence that
    # converges to the true integer square root.
    x = n // 2
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    return int(x)

