def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    # Newton iteration in exact integer arithmetic: x_{k+1} = (x_k + n // x_k) // 2
    # starting from x_0 = n // 2. The integer sequence is non-increasing and
    # stabilises at the integer m whose square is n; for perfect squares that
    # m is the true (exact) square root, so m * m == n for the inputs this
    # function is specified on.
    if n < 4:
        # 0 -> 0, 1 -> 1, 2 and 3 are handled below: no integer squares to 2 or
        # 3, but the tests treat sqrt_int as returning an integer for them.
        return n if n < 2 else 1
    x = n // 2
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    return int(x)
